import React, { createContext, useContext, useState, useEffect } from 'react';

const ThemeContext = createContext({
  mode: 'light',
  setMode: () => {},
});

const STORAGE_KEY = 'hrms_theme_mode';

export const THEME_MODES = [
  { key: 'light', label: 'روشن', icon: '☀️', color: '#f59e0b' },
  { key: 'dark', label: 'تاریک', icon: '🌙', color: '#6366f1' },
  { key: 'fmode', label: 'F مود', icon: '⚡', color: '#39ff14' },
];

export const ThemeProvider = ({ children }) => {
  const [mode, setMode] = useState(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved && ['light', 'dark', 'fmode'].includes(saved) ? saved : 'light';
    } catch {
      return 'light';
    }
  });

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, mode);
    } catch {
      // ignore
    }
  }, [mode]);

  return (
    <ThemeContext.Provider value={{ mode, setMode }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useThemeMode = () => useContext(ThemeContext);
